contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, uint256 v, uint8 tosCount) public {
        uint8 n = tosCount;
        if (n == 0) { n = 1; }
        n = (n % 4) + 1;

        GoodCallee good = new GoodCallee();

        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) tos[i] = address(good);

        bool ok;
        bool ret;
        try c.transfer(from, address(good), tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        assertTrue(!ok || ret);
    }
}

